const input = $input.first().json || {};
const prompt = String(input.query || input.image_prompt || 'cinematic frame, high quality, detailed, 4k').trim();

const defaultVertexApiKey = 'AQ.Ab8RN6J1kfXqFfeDQ90QJH4ZbwQGGrBPFV5eq4LynPupoF4L0Q';
const defaultGeminiApiKey = 'AIzaSyDROrxaDIoSTNRuSzVL4M0UXG7eHzsAMZg';
const vertexProjectDefault = 'gen-lang-client-0571009024';

function extractChatId(text) {
  if (!text) return '';
  const m = String(text).match(/chat[_\s-]*id\s*[:=]\s*(\d{6,})/i);
  return m?.[1] || '';
}

function out(obj, binary) {
  return [{ json: obj, ...(binary ? { binary } : {}) }];
}

function normalizeError(err) {
  const message = err?.response?.body?.error?.message || err?.message || 'unknown';
  const code = err?.response?.body?.error?.code || err?.statusCode || null;
  const status = err?.response?.body?.error?.status || null;
  return { message, code, status };
}

function normalizeAspect(v) {
  if (!v) return '';
  const raw = String(v).trim().toLowerCase().replace('х', ':').replace('x', ':').replace(/\s+/g, '');
  const map = {
    '1:1': '1:1',
    '3:4': '3:4',
    '4:3': '4:3',
    '9:16': '9:16',
    '16:9': '16:9',
  };
  return map[raw] || '';
}

function normalizeSize(v) {
  if (!v) return '';
  const raw = String(v).trim().toUpperCase().replace(/\s+/g, '');
  if (raw === '1K' || raw === '2K' || raw === '4K') return raw;
  return '';
}

function normalizeMime(v) {
  if (!v) return '';
  const raw = String(v).trim().toLowerCase();
  if (raw === 'png' || raw === 'image/png') return 'image/png';
  if (raw === 'jpg' || raw === 'jpeg' || raw === 'image/jpeg') return 'image/jpeg';
  if (raw === 'webp' || raw === 'image/webp') return 'image/webp';
  return '';
}

function normalizePersonGeneration(v) {
  if (!v) return '';
  const raw = String(v).trim().toLowerCase();

  if (
    raw.includes('all ages') ||
    raw.includes('all') ||
    raw.includes('allow') ||
    raw.includes('разреш') ||
    raw.includes('включ') ||
    raw.includes('да') ||
    raw.includes('любой')
  ) {
    return 'ALLOW_ALL';
  }

  if (raw.includes('adult') || raw.includes('18+') || raw.includes('взросл')) {
    return 'ALLOW_ADULT';
  }

  if (
    raw.includes('deny') ||
    raw.includes('off') ||
    raw.includes('none') ||
    raw.includes('disable') ||
    raw.includes('запрет') ||
    raw.includes('выключ') ||
    raw.includes('нельзя')
  ) {
    return 'DONT_ALLOW';
  }

  return '';
}

function normalizeModel(v) {
  if (!v) return '';
  const raw = String(v).trim().toLowerCase();

  if (raw.includes('nano banana pro') || raw.includes('nanobanana pro') || raw.includes('flow pro')) {
    return 'gemini-3-pro-image-preview';
  }
  if (raw.includes('nano banana') || raw.includes('nanobanana')) {
    return 'gemini-2.5-flash-image';
  }
  if (raw.includes('3-pro-image') || raw.includes('gemini-3-pro-image-preview')) {
    return 'gemini-3-pro-image-preview';
  }
  if (raw.includes('2.5-flash-image') || raw.includes('flash image')) {
    return 'gemini-2.5-flash-image';
  }

  // If user already sent a raw model id, keep it.
  if (/^gemini[-\w.]+$/i.test(String(v).trim())) return String(v).trim();
  return '';
}

function parseFlowCfgFromText(text) {
  const src = String(text || '');
  const result = {};

  const cmd = src.match(/\/flowcfg\s+([^\n]+)/i)?.[1] || '';
  if (cmd) {
    const tokens = cmd.split(/\s+/).filter(Boolean);
    for (const token of tokens) {
      const [k, ...rest] = token.split('=');
      if (!k || rest.length === 0) continue;
      result[String(k).toLowerCase()] = rest.join('=').trim();
    }
  }

  const lines = src.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const keyMap = {
    model: 'model',
    'модель': 'model',
    'aspect ratio': 'aspect',
    'aspect': 'aspect',
    'ratio': 'aspect',
    'соотношение': 'aspect',
    'output resolution': 'size',
    'resolution': 'size',
    'image size': 'size',
    'size': 'size',
    'разрешение': 'size',
    'output format': 'format',
    'format': 'format',
    'формат': 'format',
    'person generation': 'person',
    'person': 'person',
    'люди': 'person',
    'персонажи': 'person',
  };

  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].toLowerCase();
    if (keyMap[l] && i + 1 < lines.length) {
      const next = lines[i + 1];
      result[keyMap[l]] = next;
    }
  }

  const modelInline = src.match(/(?:model|модель)\s*[:=]?\s*([^\n,;]+)/i)?.[1];
  const aspectInline = src.match(/(?:aspect\s*ratio|aspect|ratio|соотношение)\s*[:=]?\s*([0-9xх:\s]+)/i)?.[1];
  const sizeInline = src.match(/(?:output\s*resolution|resolution|image\s*size|size|разрешение)\s*[:=]?\s*([124]\s*[kк])/i)?.[1];
  const formatInline = src.match(/(?:output\s*format|format|формат)\s*[:=]?\s*(png|jpg|jpeg|webp|image\/png|image\/jpeg|image\/webp)/i)?.[1];
  const personInline = src.match(/(?:person\s*generation|person|люди|персонажи)\s*[:=]?\s*([^\n,;]+)/i)?.[1];

  if (modelInline) result.model = modelInline;
  if (aspectInline) result.aspect = aspectInline;
  if (sizeInline) result.size = sizeInline;
  if (formatInline) result.format = formatInline;
  if (personInline) result.person = personInline;

  return result;
}

function resolveSettings(inputObj, text) {
  const parsed = parseFlowCfgFromText(text);

  const model = normalizeModel(
    inputObj.vertex_model || inputObj.model || inputObj.flow_model || parsed.model || 'gemini-3-pro-image-preview',
  ) || 'gemini-3-pro-image-preview';

  const aspectRatio = normalizeAspect(
    inputObj.aspect_ratio || inputObj.aspectRatio || inputObj.ratio || inputObj.image_aspect_ratio || parsed.aspect || '1:1',
  ) || '1:1';

  const imageSize = normalizeSize(
    inputObj.image_size || inputObj.size || inputObj.output_resolution || parsed.size || '1K',
  ) || '1K';

  const outputMimeType = normalizeMime(
    inputObj.output_format || inputObj.format || inputObj.mime_type || parsed.format || 'png',
  ) || 'image/png';

  const personGeneration = normalizePersonGeneration(
    inputObj.person_generation || inputObj.personGeneration || parsed.person || 'allow all ages',
  ) || 'ALLOW_ALL';

  return { model, aspectRatio, imageSize, outputMimeType, personGeneration };
}

try {
  const chatId = String(input.chat_id || extractChatId(prompt) || '7326497224');

  const preferredProvider = String(input.image_provider || input.provider || '').toLowerCase();
  const userKey = String(input.gemini_api_key || input.vertex_api_key || '').trim();
  const apiKey = userKey || defaultVertexApiKey;

  const settings = resolveSettings(input, prompt);
  const useVertex = preferredProvider.includes('vertex') || preferredProvider.includes('flow') || apiKey.startsWith('AQ.');

  let url;
  let body;

  if (useVertex) {
    const projectId = String(input.vertex_project_id || vertexProjectDefault).trim();
    const model = settings.model;

    url = `https://aiplatform.googleapis.com/v1/projects/${projectId}/locations/global/publishers/google/models/${model}:generateContent?key=${apiKey}`;
    body = {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        responseModalities: ['TEXT', 'IMAGE'],
        imageConfig: {
          aspectRatio: settings.aspectRatio,
          imageSize: settings.imageSize,
          personGeneration: settings.personGeneration,
          imageOutputOptions: {
            mimeType: settings.outputMimeType,
          },
        },
      },
    };
  } else {
    const key = apiKey || defaultGeminiApiKey;
    url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-image:generateContent?key=${key}`;
    body = {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        responseModalities: ['TEXT', 'IMAGE'],
      },
    };
  }

  const geminiData = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: { 'Content-Type': 'application/json' },
    body,
    json: true,
  });

  const parts = geminiData?.candidates?.[0]?.content?.parts || [];
  const inline = parts.find((p) => p?.inlineData)?.inlineData;

  if (!inline?.data) {
    return out({
      status: 'error',
      chat_id: chatId,
      image_url: '',
      image_mime_type: '',
      image_b64_preview: '',
      provider_task_id: '',
      report_for_manager: 'Gemini/Vertex не вернул изображение. Давай сделаем на другом движке: /engine pollinations',
      raw_summary: {
        provider: useVertex ? 'vertex' : 'gemini',
        settings,
        parts_keys: parts.map((p) => Object.keys(p || {})),
      },
    });
  }

  const mime = inline.mimeType || settings.outputMimeType || 'image/png';
  const b64 = inline.data;
  const ext = mime.includes('jpeg') ? 'jpg' : (mime.includes('webp') ? 'webp' : 'png');

  return out(
    {
      status: 'ok',
      chat_id: chatId,
      image_url: '',
      image_mime_type: mime,
      image_b64_preview: b64.slice(0, 120),
      provider_task_id: '',
      report_for_manager: `Gemini/Vertex сгенерировал изображение. Настройки: model=${settings.model}, ratio=${settings.aspectRatio}, size=${settings.imageSize}, format=${settings.outputMimeType}, person=${settings.personGeneration}. Отправляю в Telegram через sendPhoto.`,
      raw_summary: { provider: useVertex ? 'vertex' : 'gemini', settings, b64_length: b64.length },
    },
    {
      image: {
        data: b64,
        mimeType: mime,
        fileName: `gemini_${Date.now()}.${ext}`,
      },
    },
  );
} catch (e) {
  const err = normalizeError(e);
  return out({
    status: 'error',
    chat_id: String(input.chat_id || '7326497224'),
    image_url: '',
    image_mime_type: '',
    image_b64_preview: '',
    provider_task_id: '',
    report_for_manager: `Ошибка Gemini/Vertex: ${err.message}. Давай сделаем на другом движке: /engine pollinations`,
    raw_summary: { provider: 'gemini_or_vertex', error: err },
  });
}

